1	/**
2	 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
5	 */
6	import { wouldExceedLimit } from "@/config/plan-limits";
7	import { emit } from "@/lib/event-bus";
8	import { assertCan } from "@/lib/permissions";
9	import { assertNotArchived } from "@/lib/soft-delete";
10	import { assertOrgScope } from "@/lib/tenant";
11	import * as issueRepo from "@/server/repositories/issue-repository";
12	import * as labelRepo from "@/server/repositories/label-repository";
13	import * as orgRepo from "@/server/repositories/organization-repository";
14	import * as projectRepo from "@/server/repositories/project-repository";
15	import * as commentRepo from "@/server/repositories/comment-repository";
16	import * as attachmentRepo from "@/server/repositories/attachment-repository";
17	import {
18	  actorEnvelope,
19	  issueResource,
20	  orgResource,
21	  projectResource,
22	  requireFound,
23	} from "./_support";
24	import type {
25	  AssignIssueInput,
26	  ChangeIssueStatusInput,
27	  CreateIssueInput,
28	  IssueFilterInput,
29	  MoveIssueInput,
30	  UpdateIssueInput,
31	} from "@/schemas/issue";
32	import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
33	import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
34	import type { Actor } from "@/types/member";
35	
36	/**
37	 * Creates an issue after four gates: tenant scope, the `issue:create`
38	 * permission, a live parent project and the plan's per-project issue quota.
39	 * Only then is a number allocated and `issue.created` published — everything
40	 * reactive (notifications, search, webhooks, the audit log) hangs off that.
41	 */
42	export async function createIssue(
43	  actor: Actor,
44	  input: CreateIssueInput,
45	): Promise<Issue> {
46	  assertOrgScope(actor, input.orgId);
47	
48	  const project = requireFound(
49	    await projectRepo.findProjectById(input.orgId, input.projectId),
50	    "Project",
51	    input.projectId,
52	  );
53	  assertNotArchived("Project", project.id, project);
54	  assertCan(actor, "issue:create", projectResource(project));
55	
56	  const org = requireFound(
57	    await orgRepo.findOrgById(input.orgId),
58	    "Organization",
59	    input.orgId,
60	  );
61	  const used = await issueRepo.countIssues(input.orgId, input.projectId);
62	  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
63	    throw new Error(
64	      `Plan ${org.plan} allows no more issues in project ${project.key}`,
65	    );
66	  }
67	
68	  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
69	  const issue = await issueRepo.insertIssue(input, actor.userId, number);
70	
71	  await emit("issue.created", {
72	    ...actorEnvelope(actor),
73	    issueId: issue.id,
74	    projectId: issue.projectId,
75	    title: issue.title,
76	    assigneeId: issue.assigneeId,
77	    priority: issue.priority,
78	  });
79	
80	  return issue;
81	}
82	
83	export async function updateIssue(
84	  actor: Actor,
85	  input: UpdateIssueInput,
86	): Promise<Issue> {
87	  assertOrgScope(actor, input.orgId);
88	
89	  const before = requireFound(
90	    await issueRepo.findIssueById(input.orgId, input.issueId),
91	    "Issue",
92	    input.issueId,
93	  );
94	  assertCan(actor, "issue:update", issueResource(before));
95	  assertNotArchived("Issue", before.id, before);
96	
97	  const after = await issueRepo.updateIssue(input);
98	
99	  await emit("issue.updated", {
100	    ...actorEnvelope(actor),
101	    issueId: after.id,
102	    projectId: after.projectId,
103	    changedFields: Object.keys(input).filter(
104	      (key) => key !== "orgId" && key !== "issueId",
105	    ),
106	  });
107	
108	  return after;
109	}
110	
111	/** Status transitions are an `issue:update`, not a separate permission. */
112	export async function changeIssueStatus(
113	  actor: Actor,
114	  input: ChangeIssueStatusInput,
115	): Promise<Issue> {
116	  assertOrgScope(actor, input.orgId);
117	
118	  const before = requireFound(
119	    await issueRepo.findIssueById(input.orgId, input.issueId),
120	    "Issue",
121	    input.issueId,
122	  );
123	  assertCan(actor, "issue:update", issueResource(before));
124	  assertNotArchived("Issue", before.id, before);
125	
126	  if (before.status === input.status) return before;
127	
128	  const after = await issueRepo.setIssueStatus(
129	    input.orgId,
130	    input.issueId,
131	    input.status,
132	  );
133	
134	  await emit("issue.status_changed", {
135	    ...actorEnvelope(actor),
136	    issueId: after.id,
137	    projectId: after.projectId,
138	    from: before.status,
139	    to: after.status,
140	  });
141	
142	  return after;
143	}
144	
145	/**
146	 * Assignment has its own permission because a member may reassign work they
147	 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
148	 * `issue.assigned` carries a non-null assignee by contract.
149	 */
150	export async function assignIssue(
151	  actor: Actor,
152	  input: AssignIssueInput,
153	): Promise<Issue> {
154	  assertOrgScope(actor, input.orgId);
155	
156	  const before = requireFound(
157	    await issueRepo.findIssueById(input.orgId, input.issueId),
158	    "Issue",
159	    input.issueId,
160	  );
161	  assertCan(actor, "issue:assign", issueResource(before));
162	  assertNotArchived("Issue", before.id, before);
163	
164	  const after = await issueRepo.setIssueAssignee(
165	    input.orgId,
166	    input.issueId,
167	    input.assigneeId,
168	  );
169	
170	  if (input.assigneeId === null) {
171	    await emit("issue.updated", {
172	      ...actorEnvelope(actor),
173	      issueId: after.id,
174	      projectId: after.projectId,
175	      changedFields: ["assigneeId"],
176	    });
177	    return after;
178	  }
179	
180	  await emit("issue.assigned", {
181	    ...actorEnvelope(actor),
182	    issueId: after.id,
183	    projectId: after.projectId,
184	    previousAssigneeId: before.assigneeId,
185	    assigneeId: input.assigneeId,
186	  });
187	
188	  return after;
189	}
190	
191	export async function archiveIssue(
192	  actor: Actor,
193	  orgId: OrgId,
194	  issueId: IssueId,
195	): Promise<Issue> {
196	  assertOrgScope(actor, orgId);
197	
198	  const issue = requireFound(
199	    await issueRepo.findIssueById(orgId, issueId),
200	    "Issue",
201	    issueId,
202	  );
203	  assertCan(actor, "issue:archive", issueResource(issue));
204	  assertNotArchived("Issue", issue.id, issue);
205	
206	  const archived = await issueRepo.archiveIssue(orgId, issueId);
207	
208	  await emit("issue.archived", {
209	    ...actorEnvelope(actor),
210	    issueId: archived.id,
211	    projectId: archived.projectId,
212	  });
213	
214	  return archived;
215	}
216	
217	/**
218	 * Board drag-and-drop. The index is presentation-only — the board renders by
219	 * `updated_at` — so a move is a status change plus a touch.
220	 */
221	export async function moveIssue(
222	  actor: Actor,
223	  input: MoveIssueInput,
224	): Promise<Issue> {
225	  return changeIssueStatus(actor, {
226	    orgId: input.orgId,
227	    issueId: input.issueId,
228	    status: input.toStatus,
229	  });
230	}
231	
232	export async function getIssue(
233	  actor: Actor,
234	  orgId: OrgId,
235	  issueId: IssueId,
236	): Promise<IssueWithRelations> {
237	  assertOrgScope(actor, orgId);
238	
239	  const issue = requireFound(
240	    await issueRepo.findIssueById(orgId, issueId),
241	    "Issue",
242	    issueId,
243	  );
244	  assertCan(actor, "issue:read", issueResource(issue));
245	
246	  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);
247	
248	  return {
249	    issue,
250	    labels: labels[issue.id] ?? [],
251	    commentCount: await commentRepo.countComments(orgId, issue.id),
252	    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
253	      .length,
254	  };
255	}
256	
257	export async function listIssues(
258	  actor: Actor,
259	  input: IssueFilterInput,
260	): Promise<Page<Issue>> {
261	  assertOrgScope(actor, input.orgId);
262	  // A cross-project list is an org-wide read; per-project visibility is
263	  // enforced when the caller opens an individual issue.
264	  assertCan(actor, "issue:read", orgResource(input.orgId));
265	  return issueRepo.listIssues(input);
266	}
267	
268	export async function getBoard(
269	  actor: Actor,
270	  orgId: OrgId,
271	  projectId: ProjectId,
272	): Promise<readonly IssueBoardColumn[]> {
273	  assertOrgScope(actor, orgId);
274	
275	  const project = requireFound(
276	    await projectRepo.findProjectById(orgId, projectId),
277	    "Project",
278	    projectId,
279	  );
280	  assertCan(actor, "issue:read", projectResource(project));
281	
282	  return issueRepo.listBoardColumns(orgId, projectId);
283	}
